class AttnMaskBuilder:
    """Builder for attention masks with caching support."""

    def __init__(self, ...):
        self.swa_mask = None

    def build_swa_mask(self, max_model_len, device):
        if self.swa_mask is None:
            self.swa_mask = torch.ones((max_model_len, max_model_len),
                                       dtype=torch.bool, device=device)
        return self.swa_mask


class AscendAttentionImpl:
    """Attention implementation for Ascend."""

    def forward(self, query, key, value, ...):
        if self.sliding_window is not None:
            max_model_len = self.vllm_config.model_config.max_model_len
            swa_mask = self.mask_builder.build_swa_mask(max_model_len,
                                                        query.device)
            attn_output = self._apply_mask(query, key, swa_mask)
        else:
            attn_output = self._forward_standard(query, key, value)
        return attn_output
